package com.irwi.fincapp.ui;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import com.irwi.fincapp.repository.AnimalRepository;import com.irwi.fincapp.session.SessionManager;import com.irwi.fincapp.sync.SyncScheduler;
public class HomeActivity extends Activity{TextView status; public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=BaseUi.root(this);SessionManager s=new SessionManager(this);l.addView(BaseUi.title(this,"FincApp"));l.addView(BaseUi.text(this,"Active farm: "+s.farmName(),18));status=BaseUi.text(this,"Pending sync: "+new AnimalRepository(this).pendingCount(),18);l.addView(status);Button cattle=BaseUi.btn(this,"🐄 Cattle");Button swine=BaseUi.btn(this,"🐖 Swine");Button poultry=BaseUi.btn(this,"🐔 Poultry");Button aura=BaseUi.btn(this,"✨ AURA Assistant");Button sync=BaseUi.btn(this,"Sync now");l.addView(cattle);l.addView(swine);l.addView(poultry);l.addView(aura);l.addView(sync);cattle.setOnClickListener(v->open("Cattle"));swine.setOnClickListener(v->open("Swine"));poultry.setOnClickListener(v->open("Poultry"));aura.setOnClickListener(v->startActivity(new Intent(this,AuraActivity.class)));sync.setOnClickListener(v->{SyncScheduler.schedule(this);BaseUi.toast(this,"Background sync scheduled");});}
 void open(String type){Intent i=new Intent(this,AnimalActivity.class);i.putExtra("type",type);startActivity(i);} protected void onResume(){super.onResume();if(status!=null)status.setText("Pending sync: "+new AnimalRepository(this).pendingCount());}}
